import json
from pathlib import Path
seq = """"""
assert len(seq) == 2471, len(seq)
Path("data/census/spancache").mkdir(parents=True, exist_ok=True)
out = Path("data/census/spancache/Q04721.json")
out.write_text(json.dumps({"sequence": {"value": seq}}, separators=(",", ":")), encoding="utf-8")
got = json.loads(out.read_text(encoding="utf-8"))["sequence"]["value"]
assert got == seq and len(got) == 2471
print("SEED_OK accession=Q04721 len=%d" % len(got))